class Solution:
    def findMaximizedCapital(
        self, k: int, w: int, profits: List[int], capital: List[int]
    ) -> int:
        h1 = [(c, p) for c, p in zip(capital, profits)]
        heapify(h1)
        h2 = []
        while k:
            while h1 and h1[0][0] <= w:
                heappush(h2, -heappop(h1)[1])
            if not h2:
                break
            w -= heappop(h2)
            k -= 1
        return w

class Solution {
    public int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {
        int n = capital.length;
        PriorityQueue<int[]> q1 = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        for (int i = 0; i < n; ++i) {
            q1.offer(new int[] {capital[i], profits[i]});
        }
        PriorityQueue<Integer> q2 = new PriorityQueue<>((a, b) -> b - a);
        while (k-- > 0) {
            while (!q1.isEmpty() && q1.peek()[0] <= w) {
                q2.offer(q1.poll()[1]);
            }
            if (q2.isEmpty()) {
                break;
            }
            w += q2.poll();
        }
        return w;
    }
}

using pii = pair<int, int>;

class Solution {
public:
    int findMaximizedCapital(int k, int w, vector<int>& profits, vector<int>& capital) {
        priority_queue<pii, vector<pii>, greater<pii>> q1;
        int n = profits.size();
        for (int i = 0; i < n; ++i) {
            q1.push({capital[i], profits[i]});
        }
        priority_queue<int> q2;
        while (k--) {
            while (!q1.empty() && q1.top().first <= w) {
                q2.push(q1.top().second);
                q1.pop();
            }
            if (q2.empty()) {
                break;
            }
            w += q2.top();
            q2.pop();
        }
        return w;
    }
};

func findMaximizedCapital(k int, w int, profits []int, capital []int) int {
	q1 := hp2{}
	for i, c := range capital {
		heap.Push(&q1, pair{c, profits[i]})
	}
	q2 := hp{}
	for k > 0 {
		for len(q1) > 0 && q1[0].c <= w {
			heap.Push(&q2, heap.Pop(&q1).(pair).p)
		}
		if q2.Len() == 0 {
			break
		}
		w += heap.Pop(&q2).(int)
		k--
	}
	return w
}

type hp struct{ sort.IntSlice }

func (h hp) Less(i, j int) bool { return h.IntSlice[i] > h.IntSlice[j] }
func (h *hp) Push(v any)        { h.IntSlice = append(h.IntSlice, v.(int)) }
func (h *hp) Pop() any {
	a := h.IntSlice
	v := a[len(a)-1]
	h.IntSlice = a[:len(a)-1]
	return v
}

type pair struct{ c, p int }
type hp2 []pair

func (h hp2) Len() int           { return len(h) }
func (h hp2) Less(i, j int) bool { return h[i].c < h[j].c }
func (h hp2) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *hp2) Push(v any)        { *h = append(*h, v.(pair)) }
func (h *hp2) Pop() any          { a := *h; v := a[len(a)-1]; *h = a[:len(a)-1]; return v }

import java.util.Map;
import java.util.TreeMap;
import java.util.List;
import java.util.ArrayList;
import java.util.Arrays;

class Solution {

    public static int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {
        if (k >= profits.length && w >= Arrays.stream(capital).max().getAsInt()) {
            return w + Arrays.stream(profits).sum();
        }
        if (w < Arrays.stream(capital).min().getAsInt()) {
            return w;
        }
        Map<Integer, List<Integer>> profitsCapitals = new TreeMap<>();
        int finishedProjectsNumber = 0;
        for (int i = 0; i < profits.length; i++) {
            if (!profitsCapitals.containsKey(profits[i])) {
                profitsCapitals.put(profits[i], new ArrayList<>());
            }
            profitsCapitals.get(profits[i]).add(capital[i]);
        }
        List<Integer> keys = new ArrayList<>(profitsCapitals.keySet());
        for (int i = keys.size() - 1; i >= 0; i--) {
            if (finishedProjectsNumber == k) {
                break;
            }
            if (profitsCapitals.get(keys.get(i)).size() == 0) {
                continue;
            }
            int min = profitsCapitals.get(keys.get(i)).stream().mapToInt(v -> v).min().getAsInt();
            if (min <= w) {
                int idx = profitsCapitals.get(keys.get(i)).indexOf(min);
                w += keys.get(i);
                profitsCapitals.get(keys.get(i)).remove(idx);
                i = keys.size();
                finishedProjectsNumber++;
            }
            if (i == 0) {
                break;
            }
        }
        return w;
    }

}

//Editorial: https://leetcode.com/problems/ipo/solutions/2959870/ipo/?orderBy=most_votes
class Solution {
public:
    int findMaximizedCapital(int k, int w, vector<int>& profits, vector<int>& capital) {
        vector<pair<int,int>> nums;
        int n=profits.size();
        for(int i=0;i<n;i++)
            nums.push_back({capital[i],profits[i]});
        sort(nums.begin(),nums.end());
        priority_queue<int> pq;
        int j=0;
        for(int i=0;i<k;i++)
        {
            while(j<n and nums[j].first<=w)
            {
                pq.push(nums[j].second);
                j+=1;
            }
            if(pq.empty())
                break;
            w+=pq.top();
            pq.pop();
        }
        return w;
    }
};
